{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance does not have EBS encryption enabled, potentially exposing stored data."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance has IMDSv1 enabled by default, which can be used to access instance metadata."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "Ensure an IAM role is attached to EC2 instance",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance does not have an IAM role attached, limiting its ability to interact with AWS services securely."
    }
  ],
  "patched_code": "resource "aws_instance" "MyFirstInstnace" {
  ami           = lookup(var.AMIS, var.AWS_REGION)
  instance_type = "t2.micro"
  availability_zone = "us-east-2a"
  key_name      = aws_key_pair.levelup_key.key_name
  vpc_security_group_ids = [aws_security_group.allow-levelup-ssh.id]
  subnet_id = aws_subnet.levelupvpc-public-1.id
  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }
  root_block_device {
    encrypted = true
  }
  iam_instance_profile = aws_iam_instance_profile.example.name
}

resource "aws_iam_instance_profile" "example" {
  name = "example-profile"
  role = aws_iam_role.example.name
}

resource "aws_iam_role" "example" {
  name        = "example-role"
  description = "An example IAM role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}",
  "fix_summary": "Enabled EBS encryption, required IMDSv2, and attached an IAM role to the EC2 instance."
}
